#!/usr/bin/env bash
# M10: backfill existing MySQL messages into the ES search index.
# Run on the server after ES is up and sql/init_es.sh has created the index:
#   bash scripts/backfill_es.sh
# Why: the AsyncIndexer only indexes messages written after ES became available;
# messages stored earlier exist only in MySQL, so a one-off backfill keeps
# keyword search complete for existing conversations.
# JSON is generated by MySQL (JSON_OBJECT) so escaping of Chinese/quotes is exact.
# ASCII only (docs/env.md pitfall 12).
set -euo pipefail

ES_HOST="${ES_HOST:-http://127.0.0.1:9200}"
MYSQL_C="docker exec -i im-mysql mysql -uroot -pim123456 im_system"

echo "[backfill] dump message rows as ES bulk NDJSON"
# Column order: action line + doc line per row. Use mysql --raw so JSON is untouched.
# mysql in this image is MariaDB-compatible client? No - it is mysql 8.0; fine.
$MYSQL_C -N -B --raw -e "
SELECT
  CONCAT('{\"index\":{\"_index\":\"im-message\",\"_id\":\"', id, '\"}}'),
  JSON_OBJECT(
    'message_id', id,
    'session_id', session_id,
    'sender_id', sender_id,
    'type', type,
    'content', IFNULL(content, ''),
    'asr_text', IFNULL(asr_text, ''),
    'file_id', file_id,
    'create_time', create_time)
FROM message" > /tmp/es_bulk.tsv

ROWS=$(wc -l < /tmp/es_bulk.tsv)
echo "[backfill] rows: $ROWS"
if [ "$ROWS" -gt 0 ]; then
  awk -F'\t' '{print $1; print $2}' /tmp/es_bulk.tsv > /tmp/es_bulk.ndjson
  echo >> /tmp/es_bulk.ndjson   # trailing newline required by _bulk
  echo "[backfill] POST /_bulk"
  curl -s -X POST "$ES_HOST/_bulk?refresh=true" \
    -H 'Content-Type: application/x-ndjson' \
    --data-binary @/tmp/es_bulk.ndjson > /tmp/es_bulk_resp.json
  echo "[backfill] response summary:"
  grep -o '"errors":[a-z]*' /tmp/es_bulk_resp.json || true
  grep -o '"failed":[0-9]*' /tmp/es_bulk_resp.json | head -1 || true
fi

echo "[backfill] ES count:"
curl -s "$ES_HOST/_count?pretty" | grep -E '"count"|"failed"' || true
echo "[backfill] done"
